[metadata] {"type": "create", "filePath": "/workspace/repo/packages/codemod/src/cli.parseFlags.ts", "content": "/**
 * The structured result of parsing CLI arguments.
 */
export type ParsedFlags = {
  /** Whether the codemod should run without writing changes to disk. */
  dry: boolean
  /** Whether the CLI should list available transforms and exit. */
  list: boolean
  /** The path the codemod should operate on. Defaults to `process.cwd()`. */
  path: string
  /** Whether the codemod should print changed file contents. */
  print: boolean
  /** The name of the transform to run, if one was provided. */
  transform: string | undefined
}

/**
 * Parses a CLI argument array into a structured {@link ParsedFlags} object.
 *
 * The first positional (non-flag) argument is used as the `path`. Recognizes
 * the `--dry` (aliased by `--dry-run`), `--list`, `--print`, and
 * `--transform <value>` flags.
 *
 * @param argv - The array of CLI argument strings (without the node/script
 *   prefixes).
 */
export function parseFlags(argv: string[]): ParsedFlags {
  const flags: ParsedFlags = {
    dry: false,
    list: false,
    path: process.cwd(),
    print: false,
    transform: undefined,
  }

  let pathSet = false

  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i]

    switch (arg) {
      case '--dry':
      case '--dry-run':
        flags.dry = true
        break
      case '--list':
        flags.list = true
        break
      case '--print':
        flags.print = true
        break
      case '--transform':
        // Consume the following argument as the transform's value.
        flags.transform = argv[i + 1]
        i++
        break
      default:
        // The first non-flag positional argument is treated as the path.
        if (arg !== undefined && !arg.startsWith('-') && !pathSet) {
          flags.path = arg
          pathSet = true
        }
        break
    }
  }

  return flags
}
