import type { Transform } from './types.js'

/**
 * The result of running a single transform.
 */
export type TransformRunResult = {
  /** The Error thrown by the transform, if it failed. */
  error?: Error
  /** The list of file paths the transform changed (empty on failure). */
  filesChanged: string[]
  /** The name of the transform that produced this result. */
  name: string
  /** Optional human-readable notes returned by the transform. */
  notes?: string[]
}

/**
 * The aggregate result of running a set of transforms.
 */
export type RunTransformsResult = {
  /** `true` if any transform threw an error. */
  failed: boolean
  /** The per-transform results, in the order the transforms were supplied. */
  results: TransformRunResult[]
}

export type RunTransformsArgs = {
  /** The ts-morph project the transforms operate on. */
  project: Project
  /** The transforms to run, in order. */
  transforms: Transform[]
}

/**
 * Runs all supplied transforms in order against a ts-morph {@link Project}.
 *
 * Execution continues past any transform that throws so every transform runs
 * regardless of earlier failures. The returned `failed` flag is `true` if any
 * transform threw.
 */
export async function runTransforms({
  project,
  transforms,
}: RunTransformsArgs): Promise<RunTransformsResult> {
  const results: TransformRunResult[] = []
  let failed = false

  for (const transform of transforms) {
    try {
      const result = await transform.apply({ project })

      results.push({
        name: transform.name,
        filesChanged: result.filesChanged,
        ...(result.notes ? { notes: result.notes } : {}),
      })
    } catch (err) {
      failed = true

      results.push({
        name: transform.name,
        error: err instanceof Error ? err : new Error(String(err)),
        filesChanged: [],
      })
    }
  }

  return { failed, results }
}
