import type { Transform } from '../types.js'

export type RunTransformArgs = {
  /** The filename to use for the in-memory source file. Defaults to `input.ts`. */
  filename?: string
  /** The TypeScript source to run the transform against. */
  source: string
  /** The transform to apply. */
  transform: Transform
}

/**
 * Test helper that runs a {@link Transform} against a single in-memory source
 * file and returns the resulting source text.
 *
 * Creates a fresh ts-morph {@link Project} backed by an in-memory file system,
 * adds `source` as `filename`, applies the transform, and returns the file's
 * full text afterwards.
 */
export async function runTransform({
  filename = 'input.ts',
  source,
  transform,
}: RunTransformArgs): Promise<string> {
  const project = new Project({ useInMemoryFileSystem: true })

  project.createSourceFile(filename, source)

  await transform.apply({ project })

  return project.getSourceFileOrThrow(filename).getFullText()
}
